// E-Book Agent - website update. Run from the project root (the folder that contains mcp, server and web).
// Backs up the old web files into _backup_web_<time>/ and writes the new ones (pages, logo pictures, colours, ports 2020).
// It also adds NEXT_PUBLIC_APP_NAME=E-Book Agent to web/.env.local if that line is missing. It reads no keys and touches nothing else.
import fs from "node:fs"; import path from "node:path"; import zlib from "node:zlib";
const FILES = {"web/app/page.tsx":"","web/app/layout.tsx":"","web/app/globals.css":"","web/app/studio/page.tsx":"","web/components/Brand.tsx":"","web/components/AuthForm.tsx":"","web/lib/api.ts":"","web/package.json":"","web/public/logo.png":"","web/public/logo-icon.png":""};
const root = process.cwd();
if (!fs.existsSync(path.join(root, "web", "app")) || !fs.existsSync(path.join(root, "server", "src"))) {
  console.error("Wrong folder. Open the terminal in the project root (the folder that contains 'web' and 'server') and run again."); process.exit(1);
}
const stamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
const bak = path.join(root, "_backup_web_" + stamp);
for (const [rel, b64] of Object.entries(FILES)) {
  const dest = path.join(root, ...rel.split("/"));
  if (fs.existsSync(dest)) { const b = path.join(bak, ...rel.split("/")); fs.mkdirSync(path.dirname(b), { recursive: true }); fs.copyFileSync(dest, b); }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, zlib.gunzipSync(Buffer.from(b64, "base64")));
  console.log("updated  " + rel);
}
const envLocal = path.join(root, "web", ".env.local");
let env = fs.existsSync(envLocal) ? fs.readFileSync(envLocal, "utf8") : "";
if (!/^NEXT_PUBLIC_APP_NAME=/m.test(env)) {
  fs.writeFileSync(envLocal, env + (env && !env.endsWith("\n") ? "\n" : "") + "NEXT_PUBLIC_APP_NAME=E-Book Agent\n");
  console.log("added    NEXT_PUBLIC_APP_NAME=E-Book Agent to web/.env.local");
}
console.log("\nDone. Old versions are in " + path.basename(bak) + ".\nNext: cd web, run  npm run build , then restart the web app (and check NEXT_PUBLIC_API_URL in web/.env.local).");
